/**
 * RGBA color as unit values (0-1 range)
 * @remarks All components are in range 0-1
 */
export type UnitRgbaArray = [number, number, number, number];

/**
 * RGB color as unit values (0-1 range)
 * @remarks All components are in range 0-1
 */
export type UnitRgbArray = [number, number, number];
